fqsat : (ℝ → ℝ) → ℚ → Prop
hfqsat : ∀ (f : ℝ → ℝ) (q : ℚ), fqsat f q ↔ ContDiff ℝ 1 f ∧ ∃ p, ↑p = f ↑q ∧ p.den = q.den
⊢ ∀ (f : ℝ → ℝ), (∀ (q : ℚ), fqsat f q) ↔ f ∈ {f | ∀ (q : ℚ), fqsat f q}

